// Dim3 is an extent along X, Y and Z, such as the size of a grid in
// blocks or of a block in threads. It has the layout of three consecutive
// unsigned int members.
type Dim3 struct {
	X, Y, Z uint32
}

// Dims returns the Dim3 {x, y, z}. Unlike CUDA's dim3, it has no default
// extents: a launch rejects a zero member.
func Dims(x, y, z uint32) Dim3 {
	return Dim3{X: x, Y: y, Z: z}
}

// GridFor returns the one-dimensional grid of blocks of block threads
// that covers n threads: Dims(ceil(n/block), 1, 1). It returns the zero
// Dim3 if block is zero, and a grid with a zero member if n is zero; a
// launch rejects both.
func GridFor(n, block uint32) Dim3 {
	if block == 0 {
		return Dim3{}
	}
	x := n / block
	if n%block != 0 {
		x++
	}
	return Dims(x, 1, 1)
}

// String returns d as XxYxZ, such as 64x1x1.
func (d Dim3) String() string {
	return fmt.Sprintf("%dx%dx%d", d.X, d.Y, d.Z)
}

// zeroExtentError reports that the extent d, described by what, such as
// "launch grid", has a zero member.
func zeroExtentError(what string, d Dim3) error {
	return fmt.Errorf("%s %v has a zero extent: %w", what, d, ErrInvalidValue)
}

